package com.novacommerce.order.integration; import static org.assertj.core.api.Assertions.*; import com.novacommerce.order.application.*; import com.novacommerce.order.domain.cart.Cart; import com.novacommerce.order.infrastructure.persistence.*; import java.time.*; import java.util.*; import java.util.concurrent.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.*; import org.testcontainers.junit.jupiter.*; import org.testcontainers.postgresql.PostgreSQLContainer;
@SpringBootTest @Testcontainers(disabledWithoutDocker=true)class OrderPostgresConcurrencyTests{@Container static final PostgreSQLContainer pg=new PostgreSQLContainer("postgres:17.5-alpine");@DynamicPropertySource static void p(DynamicPropertyRegistry r){r.add("spring.datasource.url",pg::getJdbcUrl);r.add("spring.datasource.username",pg::getUsername);r.add("spring.datasource.password",pg::getPassword);r.add("order.auth.issuer",()->"test");r.add("order.auth.audience",()->"test");r.add("order.auth.jwks-uri",()->"http://127.0.0.1:1");r.add("order.catalog-base-url",()->"http://127.0.0.1:1");r.add("order.inventory-base-url",()->"http://127.0.0.1:1");}@Autowired CartRepository carts;@Autowired OrderRepository orders;@Autowired CheckoutTransactions tx;
@BeforeEach void clean(){orders.deleteAll();carts.deleteAll();}
@Test void concurrentDifferentKeysCanCreateOnlyOneOrderForCart()throws Exception{runConcurrent(false);assertThat(orders.count()).isEqualTo(1);}
@Test void concurrentSameKeyReturnsOneLogicalOrder()throws Exception{List<UUID>ids=runConcurrent(true);assertThat(ids).hasSize(20).containsOnly(ids.getFirst());assertThat(orders.count()).isEqualTo(1);}
private List<UUID>runConcurrent(boolean sameKey)throws Exception{UUID owner=UUID.randomUUID(),variant=UUID.randomUUID();Cart cart=new Cart(owner,Instant.now());cart.add(variant,1,Instant.now());carts.save(cart);var snapshot=tx.snapshot(owner,cart.getId());var catalog=List.of(new com.novacommerce.order.infrastructure.client.CatalogClient.Variant(variant,UUID.randomUUID(),"P","p","V","S",Map.of(),new com.novacommerce.order.infrastructure.client.CatalogClient.Price(new java.math.BigDecimal("1.00"),"USD")));ExecutorService pool=Executors.newFixedThreadPool(20);CountDownLatch start=new CountDownLatch(1);List<Future<UUID>>fs=new ArrayList<>();for(int i=0;i<20;i++){String key=sameKey?"same-key":"k"+i;fs.add(pool.submit(()->{start.await();try{return tx.create(owner,key,snapshot,catalog).getId();}catch(Exception e){return null;}}));}start.countDown();List<UUID>ids=new ArrayList<>();for(Future<UUID>f:fs){UUID id=f.get();if(id!=null)ids.add(id);}pool.shutdown();return ids;}}
